import csv,io,time

def render_before(rows):
    time.sleep(0.001)
    return render_after(rows)

def render_after(rows):
    stream=io.StringIO(newline='')
    writer=csv.writer(stream,lineterminator='\n')
    writer.writerow(['order','quantity'])
    writer.writerows((row['order'],row['quantity']) for row in rows)
    return stream.getvalue()

def export(rows,variant):
    time.sleep(0.090)
    return {'csv':(render_before if variant=='before' else render_after)(rows),'completed':len(rows),'errors':0}
